<script setup lang="ts">import {Search,FilePenLine,UploadCloud,CheckCircle2,FolderOpen,ArrowRight,BookOpen} from 'lucide-vue-next'
const guided=ref(false)
const currentGuide=ref(0)
const steps=[{icon:Search,name:'1. Chọn thủ tục',desc:'Mở Danh mục thủ tục, tìm theo tên hoặc lọc theo lĩnh vực.'},{icon:FilePenLine,name:'2. Điền thông tin',desc:'Nhập thông tin người nộp và các trường bắt buộc. Có thể lưu bản nháp.'},{icon:UploadCloud,name:'3. Tải giấy tờ',desc:'Đính kèm các giấy tờ PDF/JPG/PNG. Hệ thống kiểm tra đủ loại giấy tờ bắt buộc.'},{icon:CheckCircle2,name:'4. Rà soát & nộp',desc:'Kiểm tra nội dung và xác nhận trước khi gửi.'},{icon:FolderOpen,name:'5. Theo dõi kết quả',desc:'Vào Hồ sơ của tôi để xem tiến độ, bổ sung giấy tờ hoặc nhận thông báo.'}]
</script>
<template><div class="space-y-4"><div><h2 class="text-xl font-black">Hướng dẫn sử dụng cổng Công dân</h2><p class="text-sm text-muted">Các thao tác cơ bản để nộp và theo dõi hồ sơ.</p></div><div class="panel flex flex-wrap items-center justify-between gap-3 p-4"><div><p class="font-bold">Hướng dẫn lần lượt từng bước</p><p class="text-xs text-muted">Phù hợp khi cần hướng dẫn đơn giản, dễ theo dõi.</p></div><button type="button" class="btn-outline" :aria-pressed="guided" @click="guided=!guided">{{guided?'Xem tất cả bước':'Xem từng bước'}}</button></div><section v-if="guided" class="panel p-4 sm:p-6" aria-label="Hướng dẫn theo từng bước"><p class="mb-2 text-sm font-bold text-brand-700">Bước {{currentGuide+1}} / {{steps.length}}</p><div aria-live="polite"><h3 class="text-lg font-extrabold">{{steps[currentGuide]?.name}}</h3><p class="mt-2 text-sm leading-loose">{{steps[currentGuide]?.desc}}</p></div><div class="mt-5 flex flex-wrap gap-2"><button type="button" class="btn-outline" :disabled="currentGuide===0" @click="currentGuide=Math.max(0,currentGuide-1)">Bước trước</button><button type="button" class="btn-primary" :disabled="currentGuide===steps.length-1" @click="currentGuide=Math.min(steps.length-1,currentGuide+1)">Bước tiếp theo</button></div></section><div v-else class="grid gap-3 md:grid-cols-2"><div v-for="s in steps" :key="s.name" class="panel flex items-start gap-3 p-4"><span class="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-blue-50 text-brand-600"><component :is="s.icon" :size="24"/></span><div><h3 class="font-extrabold">{{s.name}}</h3><p class="mt-1 text-sm leading-relaxed text-muted">{{s.desc}}</p></div></div></div><div class="panel space-y-3 p-5"><h3 class="section-label"><BookOpen :size="21"/>Câu hỏi thường gặp</h3><details v-for="item in [{q:'Có thể lưu hồ sơ để tiếp tục sau không?',a:'Có. Sau khi hoàn thành biểu mẫu, hệ thống tạo bản nháp trong PostgreSQL. Bạn có thể mở lại từ Hồ sơ của tôi.'},{q:'Tại sao nút Nộp bị khóa?',a:'Bạn chưa bổ sung đủ loại giấy tờ bắt buộc hoặc chưa xác nhận thông tin ở bước cuối.'},{q:'Có thể dùng dữ liệu thật không?',a:'Không nên sử dụng dữ liệu cá nhân thật trong bản demo vì hệ thống chưa tích hợp toàn bộ biện pháp an toàn, định danh OIDC và kiểm dịch tệp.'},{q:'Có thể nộp phí trong hệ thống không?',a:'Chưa. Thanh toán là hạng mục phát triển sau; các mức phí hiển thị chỉ mang tính minh họa.'}]" :key="item.q" class="rounded-lg border p-3"><summary class="cursor-pointer font-bold text-brand-800">{{item.q}}</summary><p class="mt-2 text-sm text-muted">{{item.a}}</p></details></div><NuxtLink class="btn-primary" to="/thu-tuc">Bắt đầu nộp hồ sơ <ArrowRight :size="16"/></NuxtLink></div></template>
